{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C17"],
      "claim": "Isradipine, a lipophilic dihydropyridine, had a mean systemic availability of 16.5% (SD 9.9%) in healthy volunteers after oral administration, an affirmative measurement below the 20% threshold; this low-F phenotype is the most relevant anchor for the query's highly lipophilic, poorly soluble polyisoprenyl quinone structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Nifedipine had an absolute oral bioavailability of 0.43 ± 0.14 in humans, above the 20% threshold; this is directionally contradictory to a low-F prediction, but its much smaller size and different absorption profile limit transfer to the large polyisoprenyl quinone query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C11"],
      "claim": "The pyrazolopyrimidinone analogue had 34% oral bioavailability in healthy volunteers, above the threshold; however, its polar sulfonamide/piperazine and smaller scaffold are not representative of the query's extreme lipophilicity, so this high-F evidence has low applicability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a large, extremely lipophilic polyisoprenyl ubiquinone (CoQ10-like). The most transferable affirmative F measurement is isradipine's low systemic availability (~16-19%) in healthy volunteers, below the 20% threshold; the high-F values for nifedipine and the pyrazolopyrimidinone come from much smaller, more soluble drugs and do not overcome the expected dissolution/absorption limitations of the query. Therefore predict low oral bioavailability at the F>=20% threshold.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query or a close structural analogue (e.g., ubiquinone/CoQ10) is present in the evidence set.",
    "The provided high-transfer records are from smaller, structurally distinct drugs; quantitative F values may not translate to the query's dissolution/lymphatic absorption-limited behavior."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

